// ============================================================
// TEMPLATE-BASED FIRST MESSAGE — NO CLAUDE CALL
// Picks from 4 template variants per transaction type.
// Injects: first name, area, beds, market price point.
// Language detection via regex — no API needed.
// ============================================================

const owner = $json;
const firstName = (owner.owner_name || 'there').split(' ')[0];
const area = owner.area || 'Dubai';
const beds = owner.beds ? owner.beds + 'BR ' : '';
const property = owner.property_ref || (beds + area);
const txType = (owner.transaction_type || 'Sale').toLowerCase();

// Language detection — regex, free, instant
const hasArabic = /[\u0600-\u06FF]/.test(owner.owner_name || '');
const lang = hasArabic ? 'ar' : 'en';

// Market data point — pick the most relevant single number
let marketLine = '';
if (owner.avg_sale_price && txType === 'sale') {
  marketLine = `Units in ${area} are currently moving at AED ${Number(owner.avg_sale_price).toLocaleString()} on average.`;
} else if (owner.avg_rent_annual && txType === 'rental') {
  marketLine = `Rentals in ${area} are achieving AED ${Number(owner.avg_rent_annual).toLocaleString()}/year right now.`;
} else if (owner.avg_price_sqft) {
  marketLine = `${area} is currently averaging AED ${Number(owner.avg_price_sqft).toLocaleString()}/sqft.`;
}

// ---- ENGLISH TEMPLATES (4 variants, rotate by day of week) ----
const enTemplates = [
  `Hi ${firstName}, I noticed your ${property} and wanted to reach out — I specialise in this area and currently have active buyers looking. ${marketLine} Would you consider listing? Happy to share more.`,
  `Hey ${firstName} — I work with buyers specifically looking in ${area} right now. ${marketLine} If you've thought about selling, this could be good timing. Worth a quick chat?`,
  `Hi ${firstName}, I'm a local agent focused on ${area} and I have a few serious buyers who've been asking about ${beds}units there. ${marketLine} Would you be open to a conversation?`,
  `${firstName}, quick question — are you open to listing your ${property}? I have buyers actively searching in ${area}. ${marketLine} No pressure, just wanted to check.`
];

// ---- ARABIC TEMPLATES (4 variants) ----
const arTemplates = [
  `مرحبا ${firstName}، أنا متخصص في منطقة ${area} وعندي مشترين جادين الحين. ${marketLine} هل تفكر في البيع؟ يسعدني أشارك معك التفاصيل.`,
  `السلام عليكم ${firstName}، عندي عملاء يبحثون عن وحدات في ${area} بالضبط. ${marketLine} لو مهتم نتكلم، ما في أي إلزام.`,
  `هلا ${firstName}، أعمل في ${area} ومعي مشترين يسألون عن ${beds}. ${marketLine} هل أنت مهتم بالبيع هذه الفترة؟`,
  `${firstName}، سؤال سريع — هل تفكر في تأجير أو بيع ${property}؟ السوق في ${area} نشيط الحين. يسعدني أساعدك.`
];

const templates = lang === 'ar' ? arTemplates : enTemplates;
const variant = new Date().getDay() % templates.length; // rotate daily
const messageText = templates[variant];

// Channel priority: WhatsApp > Email > SMS
const channel = owner.phone_wa ? 'whatsapp' : (owner.email ? 'email' : 'sms');

return [{
  json: {
    message_text: messageText,
    owner_id: owner.id,
    owner_name: owner.owner_name,
    first_name: firstName,
    phone_wa: owner.phone_wa,
    email: owner.email,
    sms_number: owner.sms_number,
    area: owner.area,
    language: lang,
    channel,
    variant_id: 'tmpl_v' + variant,
    // Update language detected via regex back to Supabase
    detected_language: lang
  }
}];
